// Expected MQTT topics from Unreal:
// unreal/factory/conveyor1/rpm
// unreal/factory/conveyor2/rpm
// unreal/factory/machine1/position
// unreal/factory/machine1/status

const topicParts = msg.topic.split('/');
const component = topicParts[2]; // conveyor1, conveyor2, machine1
const dataType = topicParts[3];  // rpm, position, status

msg.component = component;
msg.dataType = dataType;
msg.timestamp = Date.now();

// Parse payload if string
if (typeof msg.payload === 'string') {
    try {
        msg.payload = JSON.parse(msg.payload);
    } catch(e) {
        msg.payload = { value: parseFloat(msg.payload) || msg.payload };
    }
}

return msg;

// Map Unreal data to Ignition tag structure
let tagPath = '';
let tagValue = null;

switch(msg.component) {
    case 'conveyor1':
        if (msg.dataType === 'rpm') {
            tagPath = '[default]Conveyor1/RPM';
            tagValue = msg.payload.value || msg.payload;
        }
        break;

    case 'conveyor2':
        if (msg.dataType === 'rpm') {
            tagPath = '[default]Conveyor2/RPM';
            tagValue = msg.payload.value || msg.payload;
        }
        break;

    case 'machine1':
        if (msg.dataType === 'position') {
            // Handle X,Y coordinates
            return [
                { topic: 'ignition/tag/write', payload: { tagPath: '[default]Machine1/X', value: msg.payload.x || 0, quality: 'GOOD', timestamp: msg.timestamp }},
                { topic: 'ignition/tag/write', payload: { tagPath: '[default]Machine1/Y', value: msg.payload.y || 0, quality: 'GOOD', timestamp: msg.timestamp }}
            ];
        } else if (msg.dataType === 'status') {
            return [
                { topic: 'ignition/tag/write', payload: { tagPath: '[default]Machine1/IsReady', value: msg.payload.isReady || false, quality: 'GOOD', timestamp: msg.timestamp }},
                { topic: 'ignition/tag/write', payload: { tagPath: '[default]Machine1/IsDone', value: msg.payload.isDone || false, quality: 'GOOD', timestamp: msg.timestamp }}
            ];
        }
        break;
}

if (tagPath && tagValue !== null) {
    msg.topic = 'ignition/tag/write';
    msg.payload = {
        tagPath: tagPath,
        value: tagValue,
        quality: 'GOOD',
        timestamp: msg.timestamp
    };
    return msg;
}

return null;

// Format data for Collector (receives from Unreal Engine)
// Match the simulator format for consistent TimescaleDB storage
const startTime = Date.now();
const deviceId = `${msg.component}_${msg.dataType}`;

// Handle different payload structures
let fields = {};
if (typeof msg.payload === 'object' && msg.payload !== null) {
    fields = msg.payload;
} else {
    fields = { value: msg.payload };
}

msg.payload = {
    device_id: deviceId,
    timestamp: msg.timestamp / 1000, // Convert ms to seconds as float
    type: 'sensor', // Use 'sensor' type like simulator for consistency
    data: {
        id: deviceId,
        name: `${msg.component} ${msg.dataType}`,
        signal_config: fields
    },
    metadata: {
        source: 'unreal_engine',
        component: msg.component,
        data_type: msg.dataType
    },
    processed_at: new Date().toISOString(),
    node_red_version: '1.0',
    topic_original: msg.topic,
    data_quality: {
        valid: true,
        latency_ms: Date.now() - startTime
    },
    category: 'Unreal',
    priority: 'high'
};

msg.topic = 'collector/ingest';
return msg;

// Expected topics from Ignition Edge:
// ignition/tag/Conveyor1/Running
// ignition/tag/Conveyor2/Running
// ignition/tag/Machine1/Running

const topicParts = msg.topic.split('/');
const component = topicParts[2];  // Conveyor1, Conveyor2, Machine1
const tagName = topicParts[3];    // Running

msg.component = component;
msg.tagName = tagName;

// Extract value from Ignition tag format
if (typeof msg.payload === 'object' && msg.payload.value !== undefined) {
    msg.tagValue = msg.payload.value;
} else {
    msg.tagValue = msg.payload;
}

node.status({
    fill: 'blue',
    shape: 'dot',
    text: `${component}.${tagName} = ${msg.tagValue}`
});

return msg;

// Send Ignition tag changes to Unreal Engine
// Map Ignition tag names to Unreal command topics

let unrealTopic = '';
let unrealCommand = {};

switch(msg.component.toLowerCase()) {
    case 'conveyor1':
        if (msg.tagName === 'Running') {
            unrealTopic = 'unreal/command/conveyor1/running';
            unrealCommand = {
                running: msg.tagValue,
                rpm: msg.tagValue ? 1500 : 0,
                timestamp: Date.now(),
                source: 'ignition'
            };
        }
        break;

    case 'conveyor2':
        if (msg.tagName === 'Running') {
            unrealTopic = 'unreal/command/conveyor2/running';
            unrealCommand = {
                running: msg.tagValue,
                rpm: msg.tagValue ? 1200 : 0,
                timestamp: Date.now(),
                source: 'ignition'
            };
        }
        break;

    case 'machine1':
        if (msg.tagName === 'Running') {
            unrealTopic = 'unreal/command/machine1/running';
            unrealCommand = {
                running: msg.tagValue,
                timestamp: Date.now(),
                source: 'ignition'
            };
        }
        break;
}

if (unrealTopic) {
    msg.topic = unrealTopic;
    msg.payload = unrealCommand;
    return msg;
}

return null;

// Validate required fields
if (!msg.payload.device_id || !msg.payload.timestamp) {
    node.warn('Missing required fields');
    return null;
}

// Increment message counter
let count = context.get('messageCount') || 0;
count++;
context.set('messageCount', count);

// Enrich with metadata
msg.enriched = {
    ...msg.payload,
    processed_at: new Date().toISOString(),
    node_red_version: '1.0',
    topic_original: msg.topic,
    data_quality: {
        valid: true,
        latency_ms: Date.now() - (msg.payload.timestamp * 1000)
    }
};

node.status({
    fill: 'green',
    shape: 'dot',
    text: `${msg.payload.device_id} (${count})`
});

return msg;

msg.payload = {
    ...msg.enriched,
    category: 'PLC',
    priority: 'high'
};
msg.topic = 'collector/ingest';
return msg;

msg.payload = {
    ...msg.enriched,
    category: 'Sensor',
    priority: 'medium'
};
msg.topic = 'collector/ingest';
return msg;

// PLC sends back running status after processing command
// msg.payload is array of coil values [Conv1, Conv2, Machine1, ...]

const coils = msg.payload;

// Coil 1 = Conveyor1 Running
if (coils[0] !== undefined) {
    const conv1Running = coils[0];
    const conv1Msg = {
        topic: 'unreal/command/conveyor1/running',
        payload: {
            running: conv1Running,
            timestamp: Date.now(),
            source: 'plc'
        }
    };
    node.send([conv1Msg, null, null]);
}

// Coil 2 = Conveyor2 Running
if (coils[1] !== undefined) {
    const conv2Running = coils[1];
    const conv2Msg = {
        topic: 'unreal/command/conveyor2/running',
        payload: {
            running: conv2Running,
            timestamp: Date.now(),
            source: 'plc'
        }
    };
    node.send([null, conv2Msg, null]);
}

// Coil 3 = Machine1 Running
if (coils[2] !== undefined) {
    const machine1Running = coils[2];
    const machine1Msg = {
        topic: 'unreal/command/machine1/running',
        payload: {
            running: machine1Running,
            timestamp: Date.now(),
            source: 'plc'
        }
    };
    node.send([null, null, machine1Msg]);
}

return null;

let count = context.get('messageCount') || 0;
let lastReset = context.get('lastReset') || Date.now();

// Reset every hour
if (Date.now() - lastReset > 3600000) {
    count = 0;
    lastReset = Date.now();
    context.set('lastReset', lastReset);
}

context.set('messageCount', count);

msg.payload = {
    total_messages: count,
    uptime_seconds: Math.floor((Date.now() - lastReset) / 1000),
    messages_per_second: (count / ((Date.now() - lastReset) / 1000)).toFixed(2)
};

node.status({
    fill: 'blue',
    shape: 'ring',
    text: `Total: ${count} msgs`
});

return msg;
